package com.library.circulation; import com.baomidou.mybatisplus.core.mapper.BaseMapper; import org.apache.ibatis.annotations.*; import java.util.*; @Mapper public interface BorrowMapper extends BaseMapper<BorrowRecord>{@Select("SELECT br.*,b.title,b.isbn,b.author_name,r.reader_no,u.real_name,bc.barcode FROM borrow_record br JOIN book b ON br.book_id=b.id JOIN reader r ON br.reader_id=r.id JOIN sys_user u ON r.user_id=u.id JOIN book_copy bc ON br.copy_id=bc.id WHERE (#{k}='' OR b.title LIKE CONCAT('%',#{k},'%') OR r.reader_no LIKE CONCAT('%',#{k},'%') OR u.real_name LIKE CONCAT('%',#{k},'%')) ORDER BY br.id DESC LIMIT #{o},#{s}")List<Map<String,Object>>search(String k,long o,long s);@Select("SELECT COUNT(*) FROM borrow_record br JOIN book b ON br.book_id=b.id JOIN reader r ON br.reader_id=r.id JOIN sys_user u ON r.user_id=u.id WHERE (#{k}='' OR b.title LIKE CONCAT('%',#{k},'%') OR r.reader_no LIKE CONCAT('%',#{k},'%') OR u.real_name LIKE CONCAT('%',#{k},'%'))")long count(String k);}
